//! `gbdt`: generated by tinymind-rs tools/import_trees/tinymind_import_trees.py
//! from a GradientBoostingClassifier. Do not edit; regenerate from the model instead.
//!
//! Integer-only and `no_std`. Inputs are `i8` on each feature's grid
//! (`quantize_features` converts a float sample).
//!
//! The output is int32 raw scores (log-odds or margins times `OUTPUT_SCALE`).
//!
//! Two equivalent forms: `forward`/`predict` walk the node pool with
//! `tinymind::tree` (smaller code), `forward_inline`/`predict_inline` run the
//! same trees compiled to nested `if`s (faster, larger). Both give the same
//! results.

// Not every program uses every item, and the trees are written as trained:
// a split can have two equal leaves, and an `else` holds a nested `if`.
#![allow(dead_code, clippy::if_same_then_else, clippy::collapsible_else_if)]

use tinymind::tree::{QGbdt, QTreeNode};

/// The input feature type.
pub type InputType = i8;
/// Number of input features.
pub const NUM_FEATURES: usize = 13;
/// Number of outputs (classes).
pub const NUM_OUTPUTS: usize = 3;
/// Number of trees.
pub const NUM_TREES: usize = 90;

/// Each feature's grid: `q = round(x / scale) + zero_point`, ties away from
/// zero, clamped to `[-128, 127]`.
pub const FEATURE_SCALE: [f32; NUM_FEATURES] = [
    0.013411765,
    0.019843137,
    0.006,
    0.07294118,
    0.31764707,
    0.011372549,
    0.018588236,
    0.0019607844,
    0.012392157,
    0.044156864,
    0.0036862744,
    0.010705883,
    5.4980392,
];
/// Each feature's zero point.
pub const FEATURE_ZERO_POINT: [i32; NUM_FEATURES] = [
    -979, -165, -411, -284, -348, -214, -146, -194, -162, -167, -258, -247, -179,
];

/// Quantize one float sample onto the feature grids (`quantizeFeatures` in
/// tinymind (C++)), bit for bit as the importer's reference does.
pub fn quantize_features(x: &[f32; NUM_FEATURES]) -> [InputType; NUM_FEATURES] {
    let mut q = [0; NUM_FEATURES];
    let grid = FEATURE_SCALE.iter().zip(&FEATURE_ZERO_POINT);
    for ((q, &x), (&scale, &zero_point)) in q.iter_mut().zip(x).zip(grid) {
        let v = x / scale;
        let r = if v >= 0.0 { v + 0.5 } else { v - 0.5 };
        let i = r.clamp(-1.0e9, 1.0e9) as i32 + zero_point;
        *q = i.clamp(-128, 127) as InputType;
    }
    q
}

const fn split(feature: i16, threshold: InputType, left: i16, right: i16) -> QTreeNode<InputType> {
    QTreeNode {
        feature,
        threshold,
        left,
        right,
        leaf_value: 0,
    }
}

const fn leaf(value: i32) -> QTreeNode<InputType> {
    QTreeNode {
        feature: -1,
        threshold: 0,
        left: -1,
        right: -1,
        leaf_value: value,
    }
}

/// The index of the largest value, the lowest on a tie.
fn argmax(v: &[i32; NUM_OUTPUTS]) -> usize {
    let mut best = (0, v[0]);
    for (c, &s) in v.iter().enumerate().skip(1) {
        if s > best.1 {
            best = (c, s);
        }
    }
    best.0
}

